package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.when;

public class ReaderBasedJsonParser_getTokenLocation_TriageGen0Test {

    private IOContext mockIoContext;
    private final Object sourceRef = new Object();

    @Before
    public void setUp() {
        mockIoContext = Mockito.mock(IOContext.class);
        when(mockIoContext.getSourceReference()).thenReturn(sourceRef);
    }

    /**
     * Helper to instantiate ReaderBasedJsonParser using reflection because 
     * the constructor parameters are complex and internal.
     */
    private ReaderBasedJsonParser createParser(String json) throws Exception {
        ReaderBasedJsonParser parser = new ReaderBasedJsonParser(
                mockIoContext, 0, new StringReader(json), null, null);
        return parser;
    }

    /**
     * Helper to set private fields via reflection to simulate parser state
     */
    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testGetTokenLocation_WhenTokenIsFieldName() throws Exception {
        // Arrange: Create a parser and force state to FIELD_NAME
        ReaderBasedJsonParser parser = createParser("{}");

        // We use reflection to set the internal state required by the method logic
        setPrivateField(parser, "_currToken", JsonToken.FIELD_NAME);
        setPrivateField(parser, "_nameInputTotal", 10L);
        setPrivateField(parser, "_nameInputRow", 1);
        setPrivateField(parser, "_tokenInputCol", 5);

        // Act
        JsonLocation location = parser.getTokenLocation();

        // Assert
        assertNotNull(location);
        assertEquals(sourceRef, location.getSourceRef());
        assertEquals(-1L, location.getByteOffset());
        assertEquals(10L, location.getCharOffset()); // _nameInputTotal maps to char offset in this context
        assertEquals(1, location.getByteOffset()); // The logic says -1L for offset, but we check fields
        // Note: JsonLocation constructor: (src, offset, charOffset, row, col)
        // Based on code: new JsonLocation(src, -1L, _nameInputTotal, _nameInputRow, _tokenInputCol);
        assertEquals(-1L, location.getByteOffset());
        assertEquals(10L, location.getCharOffset());
        assertEquals(1, location.getLineNr());
        assertEquals(5, location.getColumnNr());
    }

    @Test
    public void testGetTokenLocation_WhenTokenIsNotFieldName() throws Exception {
        // Arrange: Create a parser and force state to something else (e.g., START_OBJECT)
        ReaderBasedJsonParser parser = createParser("{}");

        setPrivateField(parser, "_currToken", JsonToken.START_OBJECT);
        setPrivateField(parser, "_tokenInputTotal", 20L);
        setPrivateField(parser, "_tokenInputRow", 2);
        // getTokenColumnNr() is called; we assume it returns a value based on internal state
        setPrivateField(parser, "_tokenInputCol", 3);

        // Act
        JsonLocation location = parser.getTokenLocation();

        // Assert
        assertNotNull(location);
        assertEquals(sourceRef, location.getSourceRef());
        assertEquals(1L, location.getByteOffset());
        assertEquals(20L, location.getCharOffset());
        assertEquals(2, location.getLineNr());
        assertEquals(3, location.getColumnNr());
    }

    @Test
    public void testGetTokenLocation_WithDifferentToken() throws Exception {
        // Arrange: Test with a different token to ensure the 'else' branch is covered thoroughly
        ReaderBasedJsonParser parser = createParser("[]");

        setPrivateField(parser, "_currToken", JsonToken.END_ARRAY);
        setPrivateField(parser, "_tokenInputTotal", 50L);
        setPrivateField(parser, "_tokenInputRow", 5);
        setPrivateField(parser, "_tokenInputCol", 10);

        // Act
        JsonLocation location = parser.getTokenLocation();

        // Assert
        assertNotNull(location);
        assertEquals(1L, location.getByteOffset());
        assertEquals(50L, location.getCharOffset());
        assertEquals(5, location.getLineNr());
        assertEquals(10, location.getColumnNr());
    }
}
